    "B": """not not not (((not (not (not not not ((not (not ((max(-10, 9, 8, -7) - min(-10, 9, 8, -7) <= 6) or (False)) or (The capital of Canada is Ottawa.)) or (1 - (2 / -10) is greater than -5)) and (9 * 4 > 9)) and not not (True)) or (10 - (3 / 2) is less than or equal to 10)) or (5 * 7 <= -6)) or (-1 * 4 + -4 * 2 <= -2 * 6)) or (-5 - (9 / 9) > 5)) and not not (-1 * 10 + 3 * 10 is less than or equal to 5 * -10)""",
