facts = {
    "The capital of Armenia is Yerevan.": True,
    "The capital of Canada is Ottawa.": True,
    "The capital of Colombia is Bogota.": True,
    "The capital of Afghanistan is Kabul.": True,
    "The capital of the Nigeria is Lagos.": False,
}


class ExactDivision(ast.NodeTransformer):
    def visit_BinOp(self, node):
        node = self.generic_visit(node)
        if isinstance(node.op, ast.Div):
            node.left = ast.Call(
                func=ast.Name(id="Fraction", ctx=ast.Load()),
                args=[node.left],
                keywords=[],
            )
        return node


def compute(source):
    for statement, truth in facts.items():
        source = source.replace(statement, str(truth))
    source = source.replace("is less than or equal to", "<=")
    source = source.replace("is greater than", ">")
    tree = ast.parse(source, mode="eval")
    tree = ast.fix_missing_locations(ExactDivision().visit(tree))
    return bool(eval(
        compile(tree, "<expression>", "eval"),
        {"__builtins__": {}, "Fraction": Fraction, "max": max, "min": min},
    ))


try:
    values = {label: compute(source) for label, source in expressions.items()}
    winners = [label for label, truth in values.items() if truth]
    answer = winners[0] if len(winners) == 1 else "UNSUPPORTED"
    result = {
        "final_answer": answer,
        "evidence": {"values": values, "arithmetic": "exact rational"},
    }
except Exception:
